  void Awake(){if(!GetComponent<QualityManager>())gameObject.AddComponent<QualityManager>();var asset=Resources.Load<TextAsset>("database-2026");if(!asset){Debug.LogError("Falta la base 2026/27.");enabled=false;return;}Career=new Career(JsonUtility.FromJson<Database>(asset.text));gameObject.AddComponent<SquadScreen>().Initialize(this);preMatch=gameObject.AddComponent<PreMatchScreen>();preMatch.Initialize(this);if(File.Exists(SavePath)){try{Career.Restore(JsonUtility.FromJson<CareerSave>(File.ReadAllText(SavePath)));}catch(Exception e){Status="No se cargó el guardado: "+e.Message;}}if(Career.Coach!=null)ClubId=Career.ManagedClub;CreateWorld();CameraSetup();Replay=gameObject.AddComponent<MatchReplay>();Replay.Initialize(this);LineReview=gameObject.AddComponent<GoalLineReview>();LineReview.Initialize(this);Hands=gameObject.AddComponent<GoalkeeperHands>();Hands.Initialize(this);Tactics=gameObject.AddComponent<TeamTactics>();Tactics.Initialize(this);Referee=gameObject.AddComponent<MatchReferee>();Referee.Initialize(this);gameObject.AddComponent<ControlledPlayerMarker>().Initialize(this);var official=new GameObject("Árbitro principal");official.transform.SetParent(transform,false);var refereeModel=official.AddComponent<NeutralReferee>();refereeModel.Initialize(this);Var=gameObject.AddComponent<MatchVar>();Var.Initialize(this,refereeModel);Broadcast=gameObject.AddComponent<BroadcastCamera>();Broadcast.Initialize(this);var mobile=gameObject.AddComponent<MobileMatchUI>();mobile.Initialize(this);matchInput=gameObject.AddComponent<MatchInput>();matchInput.Configure(mobile);if(Career.Coach==null)gameObject.AddComponent<CoachOnboarding>().Initialize(this);}
  public bool Save(){try{var text=JsonUtility.ToJson(Career.Snapshot(),true);Directory.CreateDirectory(Application.persistentDataPath);File.WriteAllText(SavePath+".tmp",text);File.Copy(SavePath+".tmp",SavePath,true);File.Delete(SavePath+".tmp");return true;}catch(Exception e){Status="No se pudo guardar: "+e.Message;return false;}}
  public bool FinishManagerSetup(CoachProfile profile,string club){Career.AssignCoach(profile,club);ClubId=club;var crowd=GetComponent<StadiumCrowd>();if(crowd)crowd.SetColors(ColorOf(club));if(!Save())return false;Screen="career";Status="Bienvenido, "+Career.Coach.DisplayName+".";return true;}
  public Material Material(Color color){var shader=Shader.Find("Universal Render Pipeline/Lit");if(!shader)shader=Shader.Find("Standard");var template=Resources.Load<Material>("DynastyLit");var m=template?new Material(template):new Material(shader);m.color=color;m.enableInstancing=true;m.SetFloat("_Smoothness",.2f);return m;}
  GameObject Shape(PrimitiveType type,Vector3 at,Vector3 scale,Color color,bool collider=false){var g=GameObject.CreatePrimitive(type);g.transform.SetParent(world);g.transform.position=at;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=Material(color);if(!collider)Destroy(g.GetComponent<Collider>());return g;}
  Color ColorOf(string id){ColorUtility.TryParseHtmlString(Career.Clubs[id].color,out var c);return c;}
  void CreateWorld(){world=new GameObject("Estadio · Football Dynasty").transform;var grass=Material(new Color(.09f,.26f,.12f));var tex=new Texture2D(128,128);var rng=new System.Random(27);for(int y=0;y<128;y++)for(int x=0;x<128;x++){float noise=(float)rng.NextDouble()*.05f;tex.SetPixel(x,y,new Color(.3f+noise,.7f+noise,.32f+noise));}tex.Apply();tex.wrapMode=TextureWrapMode.Repeat;grass.SetTexture("_BaseMap",tex);grass.SetTextureScale("_BaseMap",new Vector2(32,22));var field=Shape(PrimitiveType.Cube,new Vector3(0,-.3f,0),new Vector3(160,.6f,120),Color.green,true);field.GetComponent<Renderer>().sharedMaterial=grass;
   gameObject.AddComponent<StadiumTurf>().Create(world);
   foreach(float z in new[]{-34f,34f})Shape(PrimitiveType.Cube,new Vector3(0,.03f,z),new Vector3(105,.03f,.12f),Color.white);
   foreach(float x in new[]{-52.5f,0,52.5f})Shape(PrimitiveType.Cube,new Vector3(x,.03f,0),new Vector3(.12f,.03f,68),Color.white);
   for(int i=0;i<72;i++){float a=i*Mathf.PI/36;var line=Shape(PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*9.15f,.035f,Mathf.Sin(a)*9.15f),new Vector3(.85f,.025f,.1f),Color.white);line.transform.rotation=Quaternion.Euler(0,-a*Mathf.Rad2Deg+90,0);}
   foreach(int side in new[]{-1,1}){foreach(float z in new[]{-20.16f,20.16f})Shape(PrimitiveType.Cube,new Vector3(side*44.25f,.03f,z),new Vector3(16.5f,.03f,.12f),Color.white);Shape(PrimitiveType.Cube,new Vector3(side*36,.03f,0),new Vector3(.12f,.03f,40.32f),Color.white);foreach(float z in new[]{-3.66f,3.66f})Shape(PrimitiveType.Cube,new Vector3(side*52.5f,1.22f,z),new Vector3(.12f,2.44f,.12f),Color.white,true);Shape(PrimitiveType.Cube,new Vector3(side*52.5f,2.44f,0),new Vector3(.12f,.12f,7.32f),Color.white,true);for(float z=-3.6f;z<3.7f;z+=.3f)Shape(PrimitiveType.Cube,new Vector3(side*55,1.22f,z),new Vector3(.025f,2.44f,.025f),new Color(.65f,.7f,.7f));for(float y=.3f;y<2.4f;y+=.3f)Shape(PrimitiveType.Cube,new Vector3(side*55,y,0),new Vector3(.025f,.025f,7.32f),Color.gray);}
   for(int stand=0;stand<4;stand++){bool longitudinal=stand<2;int sign=stand%2==0?-1:1;float length=longitudinal?116:73;for(int row=0;row<12;row++){float depth=(longitudinal?39:60)+row*1.3f;Shape(PrimitiveType.Cube,longitudinal?new Vector3(0,row*.8f,sign*depth):new Vector3(sign*depth,row*.8f,0),longitudinal?new Vector3(length,.8f,1.3f):new Vector3(1.3f,.8f,length),new Color(.22f,.27f,.31f));}float outer=longitudinal?55:76;Shape(PrimitiveType.Cube,longitudinal?new Vector3(0,15,sign*outer):new Vector3(sign*outer,15,0),longitudinal?new Vector3(length,18,.7f):new Vector3(.7f,18,length),new Color(.23f,.27f,.3f));Shape(PrimitiveType.Cube,longitudinal?new Vector3(0,24,sign*(outer-3)):new Vector3(sign*(outer-3),24,0),longitudinal?new Vector3(length,.35f,8):new Vector3(8,.35f,length),new Color(.45f,.51f,.56f));}
   gameObject.AddComponent<StadiumCrowd>().Initialize(this,ColorOf(ClubId));var sun=new GameObject("Sol").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.2f;sun.color=new Color(1,.94f,.82f);sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(42,-28,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.45f,.57f,.7f);RenderSettings.ambientEquatorColor=new Color(.23f,.3f,.37f);RenderSettings.ambientGroundColor=new Color(.12f,.15f,.1f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.62f,.7f,.72f);RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.0025f;gameObject.AddComponent<StadiumLighting>().Configure(sun);
  }
  void CameraSetup(){MatchCamera=Camera.main;if(!MatchCamera)MatchCamera=new GameObject("Cámara televisiva").AddComponent<Camera>();MatchCamera.tag="MainCamera";if(!FindFirstObjectByType<AudioListener>())MatchCamera.gameObject.AddComponent<AudioListener>();MatchCamera.transform.position=new Vector3(0,30,44);MatchCamera.transform.LookAt(Vector3.zero);MatchCamera.fieldOfView=55;MatchCamera.nearClipPlane=.1f;MatchCamera.farClipPlane=350;MatchCamera.backgroundColor=new Color(.55f,.66f,.75f);MatchCamera.allowHDR=!Application.isMobilePlatform;var cameraData=MatchCamera.GetUniversalAdditionalCameraData();cameraData.renderShadows=true;cameraData.renderPostProcessing=!Application.isMobilePlatform;}
  public void SetDifficulty(MatchDifficulty level){if(!System.Enum.IsDefined(typeof(MatchDifficulty),level))return;Career.Difficulty=level;Save();}
  public void StartMatch(){if(Running||Screen=="match")return;var preview=MatchPreview.Create(Career,ClubId);if(preview==null){Status="No hay partido de liga pendiente para este club.";return;}preMatch.Open(preview);}
  public void ConfirmMatch(){if(Screen!="prematch"||Running)return;BeginMatch();}
  private void BeginMatch(){var league=Career.Data.leagues.FirstOrDefault(l=>l.clubs.Contains(ClubId));if(league==null){Status="Este club es propietario de jugadores externos; no participa en las seis ligas.";return;}var pair=Career.NextLeague(league.id).FirstOrDefault(p=>p.Contains(ClubId));if(pair==null){Status="No hay partido de liga pendiente.";return;}Hands.Drop();LineReview.NewMatch();Replay.NewMatch();Referee.Reset();Time.timeScale=1;ActiveFixture=new MatchResult{home=pair[0],away=pair[1],competition=league.id};foreach(var a in Agents)Destroy(a.gameObject);Agents.Clear();if(Ball)Destroy(Ball.gameObject);for(int team=0;team<2;team++){string id=team==0?pair[0]:pair[1];var ids=Career.Team(id).lineup;for(int i=0;i<ids.Length;i++){var agent=new GameObject(Career.Players[ids[i]].name).AddComponent<FootballAgent>();agent.Initialize(this,Career.Players[ids[i]],team,i,ColorOf(id));Agents.Add(agent);}}
   var ball=GameObject.CreatePrimitive(PrimitiveType.Sphere);ball.name="Balón · 430 gramos";ball.AddComponent<BallRefereeContact>().Referee=Referee;ball.transform.localScale=Vector3.one*.22f;ball.GetComponent<Renderer>().sharedMaterial=FootballAppearance.BallMaterial(this);Ball=ball.AddComponent<Rigidbody>();ball.AddComponent<BallAerodynamics>().Initialize(this);Ball.mass=.43f;Ball.linearDamping=.12f;Ball.angularDamping=.05f;Ball.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;Ball.interpolation=RigidbodyInterpolation.Interpolate;var pm=new PhysicsMaterial("Balón"){bounciness=.55f,dynamicFriction=.3f,staticFriction=.3f};ball.GetComponent<SphereCollider>().sharedMaterial=pm;Clock=0;HomeGoals=AwayGoals=0;Running=true;Finished=false;Screen="match";Kickoff(0);}
  public void ExpectReception(FootballAgent player){IntendedReceiver=player;ReceptionDeadline=Time.fixedTime+2.2f;}
  public void NotifyReception(FootballAgent player,bool deliberate){if(!player||ActiveFixture==null||(Hands&&Hands.IsHolding&&Hands.Owner!=player))return;if(deliberate&&player==IntendedReceiver)player.Animation.Trigger(PlayerAction.Receive);if(player==IntendedReceiver||player.Team!=(ClubId==ActiveFixture?.home?0:1))IntendedReceiver=null;if(!Running||IsCelebrating||Replay.IsPlaying||Referee.HasRestart||Time.timeScale==0||!player||player.Data.club!=ClubId)return;int ownTeam=ActiveFixture.home==ClubId?0:1;if(ControlSelection.CanReceive(ownTeam,player.Team,deliberate,Ball.linearVelocity.magnitude,Time.unscaledTime,manualSwitchUntil))Controlled=player;}
  public void ResetBallTracking(){previousBall=Ball.position;}
  void Kickoff(int team){Hands.Drop();if(Var)Var.Clear();celebrationRemaining=0;CelebratingTeam=-1;Referee.Reset();Referee.SetKickoff(team);IntendedReceiver=null;manualSwitchUntil=0;Tactics.ResetPossession();foreach(var a in Agents)a.ResetPosition();var striker=Agents.First(a=>a.Team==team&&a.Data.position=="DEL");striker.Body.position=new Vector3(team==0?-1:1,.95f,0);Ball.position=new Vector3(0,.2f,0);Ball.linearVelocity=Vector3.zero;Ball.angularVelocity=Vector3.zero;kickoffDelay=1;Controlled=Agents.First(a=>a.Data.club==ClubId&&a.Data.position=="DEL");previousBall=Ball.position;}
  void Update(){if(!Running||Replay.IsPlaying||LineReview.IsPlaying||(Var&&Var.IsPlaying))return;var input=matchInput.Read(MatchCamera);if(input.Pause)Time.timeScale=Time.timeScale==0?1:0;if(Time.timeScale==0||IsCelebrating)return;
   if(Referee.HasRestart){direction=Vector3.zero;sprint=false;if(input.Shoot)Controlled.Kick(false);if(input.Pass)Controlled.Kick(true);return;}
   direction=input.Movement;sprint=input.Sprint;if(input.Switch){Controlled=Agents.Where(a=>a.Data.club==ClubId&&a.Data.position!="POR").OrderBy(a=>Vector3.Distance(a.transform.position,Ball.position)).First();manualSwitchUntil=Time.unscaledTime+.45f;}if(input.Slide)Controlled.TrySlide(direction);if(input.Shoot)Controlled.Kick(false);if(input.Pass)Controlled.Kick(true);
  }
  void FixedUpdate(){
   if(!Running||Replay.IsPlaying||LineReview.IsPlaying||(Var&&Var.IsPlaying))return;
   if(IsCelebrating){foreach(var actor in Agents)actor.Body.linearVelocity=Vector3.zero;Ball.linearVelocity=Vector3.zero;Ball.angularVelocity=Vector3.zero;celebrationRemaining=Mathf.Max(0,celebrationRemaining-Time.fixedDeltaTime);Replay.Record();if(!IsCelebrating){Replay.Goal();Kickoff(restartAfterGoal);FinishIfTimeExpired();}return;}
   if(!Referee.HasRestart&&!Referee.DropInFlight)Clock+=Time.fixedDeltaTime;
   Referee.Tick(Time.fixedDeltaTime);if(Referee.HasRestart||Referee.DropInFlight){Replay.Record();return;}
   kickoffDelay=Mathf.Max(0,kickoffDelay-Time.fixedDeltaTime);
   if(kickoffDelay<=0){Tactics.Tick(Time.fixedDeltaTime);foreach(var actor in Agents){actor.Step(actor==Controlled?direction:Vector3.zero,actor==Controlled,actor==Controlled?sprint:actor.Decision.Sprint);if(Referee.IsStopped)break;}}
   if(Referee.IsStopped){Replay.Record();return;}
   var ballAt=Ball.position;
   int goal=GoalRules.CrossedGoal(previousBall.x,previousBall.y,previousBall.z,ballAt.x,ballAt.y,ballAt.z);
   var exit=BallBoundary.Evaluate(new PitchPoint(previousBall.x,previousBall.z),new PitchPoint(ballAt.x,ballAt.z),Referee.LastTouchTeam);
   float goalFraction=goal==0?2:(Mathf.Sign(ballAt.x)*52.61f-previousBall.x)/(ballAt.x-previousBall.x);
   if(exit.Kind!=RestartKind.None&&(goal==0||(exit.Kind==RestartKind.ThrowIn&&exit.Fraction<goalFraction))){Referee.OutOfPlay(exit);IntendedReceiver=null;Replay.Record();return;}
   if(goal!=0)Var.Register(VarIncidentKind.Goal,VarDecisions.Goal(true,Referee.GoalIsValid(goal>0?0:1)),Referee.GoalIsValid(goal>0?0:1)?"El balón cruzó completamente y no consta una infracción invalidante.":"La reanudación no permite ese gol directo.");
   if(goal==0||Referee.GoalIsValid(goal>0?0:1))LineReview.Observe(previousBall,ballAt,goal,goal!=0);
   if(goal!=0){if(!Referee.GoalIsValid(goal>0?0:1)){Referee.RejectIndirectGoal(goal>0?1:0);return;}if(goal>0)HomeGoals++;else AwayGoals++;Replay.Record();Replay.Goal();BeginGoalCelebration(goal>0?0:1);}else Replay.Record();
   previousBall=Ball.position;
   if(!IsCelebrating&&!LineReview.IsPlaying)FinishIfTimeExpired();
  }

  public void BeginGoalCelebration(int scoringTeam){if(!Running||IsCelebrating||scoringTeam<0||scoringTeam>1)return;CelebrationLeader=Agents.Where(a=>a.Team==scoringTeam&&a.Data.position!="POR").OrderBy(a=>(a.Body.position-Ball.position).sqrMagnitude).First();CelebratingTeam=scoringTeam;restartAfterGoal=1-scoringTeam;celebrationRemaining=4.5f;direction=Vector3.zero;IntendedReceiver=null;Referee.Reset();foreach(var actor in Agents){actor.CancelSlide();actor.Body.linearVelocity=Vector3.zero;}Ball.linearVelocity=Vector3.zero;Status="¡GOOOL! · "+Career.Clubs[scoringTeam==0?ActiveFixture.home:ActiveFixture.away].name;}
  void FinishIfTimeExpired(){if(Clock<180)return;Running=false;Finished=true;ActiveFixture.hg=HomeGoals;ActiveFixture.ag=AwayGoals;Time.timeScale=1;}
  void InitStyles(){if(title!=null)return;title=new GUIStyle(GUI.skin.label){fontSize=22,fontStyle=FontStyle.Bold};cardStyle=new GUIStyle(GUI.skin.box){alignment=TextAnchor.UpperLeft,fontSize=14,padding=new RectOffset(10,10,10,8),wordWrap=true};}
  void Card(Player p,Action pick,bool selected=false){var old=GUI.backgroundColor;GUI.backgroundColor=p.legend?new Color(.65f,.5f,.2f):selected?new Color(.45f,.65f,.34f):new Color(.14f,.34f,.27f);GUILayout.BeginVertical(GUI.skin.box,GUILayout.Width(145),GUILayout.Height(160));GUILayout.Label(p.rating+" · "+p.position,title);GUILayout.Label(p.name);GUILayout.Label($"{p.stats.RIT} RIT   {p.stats.TIR} TIR   {p.stats.PAS} PAS\n{p.stats.REG} REG   {p.stats.DEF} DEF   {p.stats.FIS} FIS");GUILayout.Label(p.legend?"LEYENDA HISTÓRICA":Career.Clubs[p.club].name);if(GUILayout.Button(selected?"Titular":"Seleccionar"))pick();GUILayout.EndVertical();GUI.backgroundColor=old;}
  void OnGUI(){if(Career==null||Replay.IsPlaying||(LineReview&&LineReview.IsPlaying)||(Var&&Var.IsPlaying)||Screen=="replays"||Screen=="onboarding"||Screen=="prematch"||Screen=="squad")return;InitStyles();GUI.matrix=Matrix4x4.TRS(Vector3.zero,Quaternion.identity,new Vector3(ScreenWidth/1280f,ScreenHeight/720f,1));GUILayout.BeginArea(new Rect(15,12,1250,Screen=="match"?220:695),GUI.skin.box);GUILayout.Label("FOOTBALL DYNASTY 27 · UNITY",title);if(Screen=="match"){GUILayout.Label($"{Career.Clubs[ActiveFixture.home].name}  {HomeGoals} : {AwayGoals}  {Career.Clubs[ActiveFixture.away].name} · {Mathf.FloorToInt(Clock/2)}′");GUILayout.Label("WASD mover · Shift correr · J/B pase · K/A tiro · L/C cambiar · Q barrida (móvil D) · P pausa");GUILayout.Label("DYNASTY IQ · Fase: "+Tactics.Possession.PhaseFor(ActiveFixture.home==ClubId?0:1)+(Controlled?" · "+Controlled.Role:""));Replay.MatchButtons();if(Finished&&GUILayout.Button("Guardar resultado y continuar carrera")){Career.Advance(ActiveFixture);Save();Finished=false;Screen="career";}if(GUILayout.Button("Salir sin guardar el partido")){Running=false;Finished=false;Time.timeScale=1;Screen="career";}GUILayout.EndArea();return;}
   GUILayout.BeginHorizontal();foreach(var screen in new[]{"career","clubs","squad","market","competitions"})if(GUILayout.Button(new Dictionary<string,string>{{"career","Carrera"},{"clubs","Elegir club"},{"squad","Once y cartas"},{"market","Fichajes"},{"competitions","Ligas y torneos"}}[screen])){Screen=screen;scroll=Vector2.zero;}GUILayout.EndHorizontal();GUILayout.Label(Career.Clubs[ClubId].name+$" · € {Career.Clubs[ClubId].budget/1000000:F1} M · Temporada {Career.Season}/{Career.Season+1} · Jornada {Math.Min(Career.Round+1,40)}/40");GUILayout.Label(Status);scroll=GUILayout.BeginScrollView(scroll);
   if(Screen=="career"){if(Career.Coach!=null)GUILayout.Label("DT · "+Career.Coach.DisplayName+" · "+Career.Coach.country,title);GUILayout.Label("Dificultad · "+Career.Difficulty);foreach(var level in new[]{MatchDifficulty.Facil,MatchDifficulty.Medio,MatchDifficulty.Dificil})if(GUILayout.Button(level.ToString(),GUILayout.Width(140))){Career.Difficulty=level;Save();}foreach(var cup in CompetitionMenu.ForClub(Career,ClubId))GUILayout.Label(CompetitionMenu.Name(cup)+" · "+CompetitionMenu.State(cup,ClubId));if(GUILayout.Button("Repeticiones guardadas"))Replay.OpenGallery();GUILayout.Label("Simulación física 11 contra 11. El partido de liga jugado se incorpora al calendario.");if(!Career.SeasonFinished&&GUILayout.Button("Jugar próximo partido"))StartMatch();if(Career.SeasonFinished&&GUILayout.Button("Iniciar siguiente temporada")){Career.StartNextSeason();Save();Status="Nueva temporada: se conservan fichajes, fondos y once.";}if(GUILayout.Button("Simular jornada")){try{Career.Advance();Save();}catch(Exception e){Status=e.Message;}}GUILayout.Label("Guardado: "+SavePath);}
   if(Screen=="clubs")foreach(var league in Career.Data.leagues){GUILayout.Label(league.name,title);GUILayout.BeginHorizontal();int i=0;foreach(var id in league.clubs){if(i++%5==0&&i>1){GUILayout.EndHorizontal();GUILayout.BeginHorizontal();}if(GUILayout.Button(Career.Clubs[id].name,GUILayout.Width(220))){ClubId=id;Career.ManagedClub=id;Save();Screen="career";GetComponent<StadiumCrowd>().SetColors(ColorOf(id));}}GUILayout.EndHorizontal();}
   if(Screen=="market"){query=GUILayout.TextField(query);var matches=Career.Data.players.Where(p=>p.club!=ClubId&&(query.Length==0||p.name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)).OrderByDescending(p=>p.name=="Lionel Messi"||p.name=="Cristiano Ronaldo"?1000:p.legend?500:p.rating).ToArray();GUILayout.BeginHorizontal();if(GUILayout.Button("Anterior"))page=Math.Max(0,page-1);if(GUILayout.Button("Siguiente"))page++;GUILayout.EndHorizontal();page=Math.Min(page,Math.Max(0,(matches.Length-1)/18));var list=matches.Skip(page*18).Take(18).ToArray();for(int i=0;i<list.Length;i++){if(i%6==0)GUILayout.BeginHorizontal();var p=list[i];Card(p,()=>offer=p);if(i%6==5||i==list.Length-1)GUILayout.EndHorizontal();}if(offer!=null){GUILayout.Label($"Comprar {offer.name} a {Career.Clubs[offer.club].name} por € {(offer.value+offer.wage*4)/1000000:F2} M (incluye prima)");if(GUILayout.Button("Confirmar oferta al propietario")){var result=Career.Buy(offer.id,ClubId,offer.club);Status=result.Message;if(result.Ok)Save();offer=null;}}}
   if(Screen=="competitions"){foreach(var league in Career.Data.leagues){GUILayout.Label(league.name,title);foreach(var row in Career.Table(league.clubs,Career.Results.Where(m=>m.competition==league.id)))GUILayout.Label($"{Career.Clubs[row.Club].name,-30}  PJ {row.Played}   Pts {row.Points}   GF {row.GF}   GC {row.GA}");}foreach(var cup in Career.Tournaments){GUILayout.Label(cup.name+" · "+cup.stage,title);if(!string.IsNullOrEmpty(cup.champion))GUILayout.Label("Campeón: "+Career.Clubs[cup.champion].name);foreach(var m in cup.games.TakeLastCompat(12))GUILayout.Label($"{Career.Clubs[m.home].name}  {m.hg}:{m.ag}  {Career.Clubs[m.away].name}");}}
   GUILayout.EndScrollView();GUILayout.EndArea();}
  int ScreenWidth=>UnityEngine.Screen.width;int ScreenHeight=>UnityEngine.Screen.height;
 }
 public static class ListExtensions {public static IEnumerable<T> TakeLastCompat<T>(this IEnumerable<T> source,int n){var a=source.ToArray();return a.Skip(Math.Max(0,a.Length-n));}}
